--region override
---初始化杂货铺列表数据
function GrocerySpecialtyNode:InitGroceryData()
    local data = GroceryMgr:GetGroceryDataByType(self:GetGroceryType())
    local productData = {}
    for _, v in ipairs(data.products) do
        if productData[checkInt(v.tab)] then
            table.insert(productData[checkInt(v.tab)], v)
        else
            productData[checkInt(v.tab)] = {v}
        end
    end
    local groceryData = {}
    for i, v in ipairs(productData) do
        ---@type SystemToggleVo
        local vo = CfUtils.SystemToggleVo( TabGroup[i])
        groceryData[i] = {
            products = v,
            text     = checkTable(vo).realName
        }
    end
    return groceryData
end

---初始化顶部页签
function GrocerySpecialtyNode:InitTopTabState()
    return true
end

---初始化杂货铺类型
function GrocerySpecialtyNode:InitGroceryType()
    return GroceryConstants.GroceryType.Specialty
end

---初始化顶部页签
function GrocerySpecialtyNode:InitTopTab()
    local tabState = self:GetTabState()
    CfUtils.SetActive(self.CommonTabToggleUp, tabState)
    if not tabState then return end
    self:SetSelectedTab(1)
    local groceryData = self:GetGroceryData()
    if not self.TabScrollView.IsListViewInit then
        self.TabScrollView:InitGridView(#groceryData, Bind(self, self.OnTabGetItemByIndex))
    else
        GameUtils.ReloadData(self.TabScrollView, #groceryData)
        self.TabScrollView:MovePanelToItemByIndex(0)
    end

end

---页签列表刷新
function GrocerySpecialtyNode:OnTabGetItemByIndex(listView, idx)
    if idx < 0 then return nil end

    local cell = listView:NewListViewItem("Cell")
    ---@type CommonTabToggleUpCell
    local nodeScr = CfUtils.GetLuaScr(cell, GroceryConstants.ScrPath.CommonTabToggleUpCell)
    if isNull(nodeScr) then return nil end

    local index = idx + 1
    local data = self:GetGroceryData()[index]
    nodeScr:FreshBaseUI(data)
    local isSelected = index == self:GetSelectedTab()
    nodeScr:FreshSelectStatus(isSelected)
    nodeScr:SetLockStatus(isSelected and 2 or 1)
    nodeScr:SetCallBack(function() --点击回调
        if index ~= self:GetSelectedTab() then --屏蔽掉重复点击当前选择的toggle
            nodeScr:FreshSelectStatus(true)
            nodeScr:SetLockStatus(2)
            local preNodeGo = self.TabScrollView:GetShownItemByItemIndex(self:GetSelectedTab() - 1)
            if not isNull(preNodeGo) then
                ---@type CommonTabToggleUpCell
                local preNodeScr = CfUtils.GetLuaScr(preNodeGo, GroceryConstants.ScrPath.CommonTabToggleUpCell)
                preNodeScr:FreshSelectStatus(false)
                preNodeScr:SetLockStatus(1)
            end
            self:SetSelectedTab(index)
            self:RefreshUI()
            self:PlaySwitchTabAnimation()
            self:RefreshCurrencyBar()
        end
    end)
    nodeScr:SetLockState(not GameUtils.IsUnlockedBySystemTogId(TabGroup[index]))

    return cell
end

function GrocerySpecialtyNode:InitData()
    Base.InitData(self)
end

function GrocerySpecialtyNode:InitHandler()
    Base.InitHandler(self)

    SetButtonAction(self.Left, Bind(self, self.TabBtnLeftOnClickHandler))
    SetButtonAction(self.Right, Bind(self, self.TabBtnRightOnClickHandler))
end

---cell点击回调
function GrocerySpecialtyNode:GroceryCellOnClickHandler(index)
    if not self:CheckTabUnlock() then
        GameUtils.Toast(localize("区域未解锁"))
        return
    end

    Base.GroceryCellOnClickHandler(self, index)
end
--endregion override

--region handler
---顶部页签左侧按钮点击回调
function GrocerySpecialtyNode:TabBtnLeftOnClickHandler()
    self.TabScrollView:MovePanelToItemByIndex(0)
end

---顶部页签右侧按钮点击回调
function GrocerySpecialtyNode:TabBtnRightOnClickHandler()
    self.TabScrollView:MovePanelToItemByIndex(#self:GetGroceryData())
end
--endregion handler

--region public
---刷新页面
function GrocerySpecialtyNode:Refresh()
    self:InitData()
    self:InitUI()
    self:RefreshUI()
    self:PlayEnterAnimation()
end

---刷新货币栏
function GrocerySpecialtyNode:RefreshCurrencyBar()
    local totalCurrencyList = GroceryUtils.GetCurrencyByGroceryType(self:GetGroceryType()) or {}
    -- 只显示对应页签需要的货币
    local currencyList = {totalCurrencyList[self:GetSelectedTab()]}
    CfUtils.RefreshTopGoods(currencyList)
end
--endregion public

--region private
---播放进入动画
function GrocerySpecialtyNode:PlayEnterAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreSynchronousPvpDialog_L")
end

---播放进入动画
function GrocerySpecialtyNode:PlaySwitchTabAnimation()
    self.Root:Stop()
    CfUtils.PlayAnimation(self.Root, "OverseaStoreSynchronousPvpDialog_T")
end

---检查区属是否开启
---@return boolean 是否满足
function GrocerySpecialtyNode:CheckTabUnlock()
    return GameUtils.IsUnlockedBySystemTogId(TabGroup[self:GetSelectedTab()])
end

---更新顶部页签UI
function GrocerySpecialtyNode:UpdateTopTabUI()
    local posX = self.Content.localPosition.x
    local viewportW = self.Viewport.rect.width
    local contentW = self.Content.rect.width
    CfUtils.SetActive(self.Left, posX < 0)
    CfUtils.SetActive(self.Right, contentW - viewportW + posX> 0)
end
--endregion private

return GrocerySpecialtyNode